import (
	"encoding/json"
	"fmt"
	"net/http"
	"sync"
)

type User struct {
	ID   int    `json:"id"`
	Name string `json:"name"`
}

type Post struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	AuthorID int    `json:"authorId"`
}

var (
	users      = []User{{ID: 1, Name: "Alice"}, {ID: 2, Name: "Bob"}}
	posts      = []Post{{ID: 1, Title: "Post 1", AuthorID: 1}, {ID: 2, Title: "Post 2", AuthorID: 2}, {ID: 3, Title: "Post 3", AuthorID: 1}}
	batchCount int
	mu         sync.Mutex
)

func batchLoadAuthors(authorIDs []int) map[int]User {
	mu.Lock()
	batchCount++
	mu.Unlock()
	result := make(map[int]User)
	for _, id := range authorIDs {
		for _, u := range users {
			if u.ID == id {
				result[id] = u
				break
			}
		}
	}
	return result
}

func main() {
	http.HandleFunc("/batch-stats", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		mu.Lock()
		count := batchCount
		mu.Unlock()
		json.NewEncoder(w).Encode(map[string]int{"batchCount": count})
	})

	http.HandleFunc("/graphql", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		authorIDs := make([]int, 0)
		seen := make(map[int]bool)
		for _, p := range posts {
			if !seen[p.AuthorID] {
				authorIDs = append(authorIDs, p.AuthorID)
				seen[p.AuthorID] = true
			}
		}
		authors := batchLoadAuthors(authorIDs)

		type PostWithAuthor struct {
			ID     int    `json:"id"`
			Title  string `json:"title"`
			Author User   `json:"author"`
		}
		var result []PostWithAuthor
		for _, p := range posts {
			result = append(result, PostWithAuthor{ID: p.ID, Title: p.Title, Author: authors[p.AuthorID]})
		}
		json.NewEncoder(w).Encode(map[string]interface{}{"data": map[string]interface{}{"posts": result}})
	})

	fmt.Println("Server on :3000")
	http.ListenAndServe(":3000", nil)
}

